import {preview,connection} from './config.js';
import {signIn,signOut} from './session.js';
import {packages,packageLabel,schedules} from '../shared/settings.js';
import {money,uid,rates,remaining,clock,orderLabels,publicBoard,publicOrder,serverTime} from '../shared/domain.js';
import {readState,subscribe,execute,initialize,pairDisplay} from './store.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',ticket:'M3 7h18v4a2 2 0 0 0 0 4v4H3v-4a2 2 0 0 0 0-4V7z M15 7v2 m0 3v2 m0 3v2',game:'M7 8h10c3 0 4 3 4 7s-2 5-4 3l-2-2H9l-2 2c-2 2-4 1-4-3s1-7 4-7z M7 11v4 m-2-2h4 m6-1h.01 m3 2h.01',tree:'M12 3 5 11h3l-4 6h16l-4-6h3L12 3z M12 17v4',clock:'M12 8v4l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',bag:'M5 7h14l1 14H4L5 7z M9 8V6a3 3 0 0 1 6 0v2',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 4a4 4 0 0 1 0 8 m6 9v-2a4 4 0 0 0-3-3 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',screen:'M3 4h18v13H3z M8 21h8 m-4-4v4',qr:'M3 3h6v6H3z M15 3h6v6h-6z M3 15h6v6H3z M15 15h2v2h-2z m4 0h2v6h-6v-2',box:'m3 7 9-5 9 5-9 5-9-5z M3 7v10l9 5 9-5V7 M12 12v10 M8 4l9 5',chart:'M4 3v18h17 M8 16v-4 m5 4V8 m5 8V5',plus:'M12 5v14 M5 12h14',arrow:'m9 5 7 7-7 7',right:'M5 12h14 m-5-5 5 5-5 5',down:'m6 9 6 6 6-6',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',sound:'m11 4-6 5H2v6h3l6 5V4z M15 8a6 6 0 0 1 0 8 m3-11a10 10 0 0 1 0 14',check:'m5 12 4 4L19 6',close:'m6 6 12 12 M18 6 6 18',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',external:'M14 3h7v7 m0-7-11 11 M10 3H3v18h18v-7',link:'m10 13 4-4 M8 16l-1 1a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0 m0 12a4 4 0 0 0 6 0l5-5a4 4 0 0 0-6-6l-1 1',print:'M6 8V3h12v5 M6 17H3V8h18v9h-3 M6 14h12v7H6z m11-3h1',menu:'M4 6h16 M4 12h16 M4 18h16',help:'M9 8a3 3 0 0 1 6 0c0 3-3 2-3 5 m0 4h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',receipt:'M5 3h14v18l-3-2-4 2-4-2-3 2V3z M8 7h8 M8 11h8 M8 15h4',heart:'M20 4c-3-2-6 0-8 2-2-2-5-4-8-2-5 4 0 9 8 16 8-7 13-12 8-16',settings:'M4 7h16 M4 17h16 M8 4v6 M16 14v6',sun:'M12 2v2 m0 16v2 M2 12h2 m16 0h2 M5 5l1 1 m12 12 1 1 M5 19l1-1 M18 6l1-1 M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;
const brand=()=>`<div class="brand"><img class="brand-original" src="/logodivermania.png" alt="Divermanía"><div>DIVERMANÍA<div class="brand-sub">CENTRO DE CONTROL</div></div></div>`;
const params=new URLSearchParams(location.search);
let state=readState(),page=params.get('page')||(location.pathname==='/televisores.html'?'screens':'overview'),view=params.get('view')||(location.pathname==='/admin.html'||location.pathname==='/televisores.html'?'staff':location.pathname==='/seguimiento.html'?'track':'menu'),timeTab='play',orderTab='kitchen',search='',role=params.get('role')||localStorage.getItem('divermania.role')||'admin';
let soundEnabled=false,audio,alarmSeen=new Set(),acknowledged=new Set(),lastAlarmBucket='',menuCat='Todos',foodSearch='',cart=readClientCart(),checkoutDraft={},modalCloseHook=null;
const active=area=>state.tickets.filter(t=>t.status==='active'&&(!area||t.area===area));
const waiting=()=>state.tickets.filter(t=>t.status==='waiting');
const openOrders=()=>state.orders.filter(o=>!['delivered','cancelled'].includes(o.status));
const nearSessions=()=>active().filter(t=>remaining(t)<=5*60000);
const initials=name=>String(name).split(' ').slice(0,2).map(x=>x[0]||'').join('').toUpperCase();
const ago=time=>Math.max(0,Math.floor((Date.now()-time)/60000));
const formatDate=time=>new Date(time).toLocaleString('es-VE',{timeZone:'America/Caracas',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});
const roleNames={admin:'Administración',cash:'Taquilla',entrance:'Entrada / tiempos',gamer:'Zona gamer',kitchen:'Cocina'};
const navItems=[['overview','grid','Vista general'],['cash','ticket','Taquilla'],['times','clock','Parque y Play'],['orders','bag','Pedidos y cocina'],['customers','users','Clientes frecuentes'],['screens','screen','Pantallas y QR'],['catalog','box','Catálogo y recetas'],['inventory','box','Inventario'],['finances','chart','Finanzas']];
const pageTitles={overview:'Vista general',cash:'Taquilla',times:'Parque y Play',orders:'Pedidos y cocina',customers:'Clientes frecuentes',screens:'Pantallas y QR',catalog:'Catálogo y recetas',inventory:'Inventario',finances:'Finanzas'};
function badge(label,color=''){return `<span class="badge ${color}">${esc(label)}</span>`;}
function orderBadge(o){return badge(orderLabels[o.status],{pending:'orange',preparing:'purple',ready:'',delivered:'gray',cancelled:'red'}[o.status]);}
function empty(title,text='',name='grid'){return `<div class="empty">${icon(name)}<strong>${esc(title)}</strong>${esc(text)}</div>`;}
function head(title,subtitle,actions=''){return `<div class="page-head"><div><div class="eyebrow">DIVERMANIA · OPERACIONES</div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`;}
function notice(){return `<div class="demo-notice"><span class="tag">${preview?'VISTA PREVIA':'FIREBASE'}</span><span>${preview?'Datos de prueba · Menú y tarifas informados · Sin cambios en la base real.':connection.error?esc(connection.error):connection.status==='live'?'Conectado al proyecto Divermanía.':'Conectando con Firebase…'}</span>${!preview?'<button class="btn text" data-action="sign-out">Cerrar sesión</button>':''}</div>`;}
function stat(label,value,foot,name,color=''){return `<div class="stat"><div class="stat-top"><span>${label}</span><span class="stat-icon ${color}">${icon(name)}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`;}
function render(){if(!preview&&view==='staff'&&!connection.role){loginScreen();return;}if(!preview&&view==='board'&&connection.status==='pairing'){pairScreen();return;}if(view==='menu'){renderMenu();return;}if(view==='track'){renderTracker();return;}if(view==='board'){renderBoard();return;}renderStaff();}
const rolePages={cash:['overview','cash','orders','customers','finances'],entrance:['overview','times','customers'],gamer:['overview','times'],kitchen:['orders']};
function renderStaff(){
 if(!preview&&connection.role!=='admin'){role=connection.role||'cash';if(!rolePages[role]?.includes(page))page=rolePages[role]?.[0]||'overview';}
 $('#app').innerHTML=`<div class="app-shell"><div class="mobile-cover" data-action="close-nav"></div><aside class="sidebar">${brand()}<a class="sidebar-client-link" href="/cliente.html" target="_blank" rel="noopener">${icon('bag')} Vista del cliente ${icon('external')}</a><div class="side-label">TU ESPACIO DE TRABAJO</div><nav class="side-nav">${navItems.filter(([id])=>preview||connection.role==='admin'||rolePages[connection.role]?.includes(id)).map(([id,i,label])=>`<button class="nav-item ${page===id?'active':''}" data-page="${id}">${icon(i)}<span>${label}</span>${id==='orders'&&openOrders().length?`<span class="nav-count">${openOrders().length}</span>`:''}</button>`).join('')}</nav><div class="side-bottom"><div class="demo-side"><strong><span class="dot"></span>Un lugar, todo conectado</strong>Comida, parque y videojuegos.<br>Cada área en su propia pantalla.</div><div class="side-profile"><span class="avatar">DM</span><div>Equipo Divermania<small>${roleNames[role]||'Administración'} · ${preview?'Vista previa':'Equipo'}</small></div><button aria-label="Ayuda" data-action="help">${icon('help')}</button></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-toggle" aria-label="Abrir menú" data-action="open-nav">${icon('menu')}</button>${icon('grid')}<span>Centro de control</span>${icon('arrow')}<strong>${pageTitles[page]||'Vista general'}</strong></div><div class="top-actions"><a class="top-shortcut" aria-label="Abrir vista del cliente" href="/cliente.html" target="_blank" rel="noopener">${icon('bag')} Vista cliente</a><a class="top-shortcut" aria-label="Preparar televisores" href="/televisores.html">${icon('screen')} Televisores</a><span class="connection"><span class="dot"></span>${preview?'Vista previa':connection.status==='live'?'Firebase en línea':'Conectando'}</span><button class="icon-btn ${soundEnabled?'active':''}" title="${soundEnabled?'Desactivar':'Activar'} sonido" aria-label="${soundEnabled?'Desactivar':'Activar'} sonido" data-action="sound">${icon('sound')}</button><select class="role-select" id="role-select" aria-label="Vista de trabajo">${Object.entries(roleNames).filter(([k])=>preview||connection.role==='admin'||k===connection.role).map(([k,v])=>`<option value="${k}" ${role===k?'selected':''}>${v}</option>`).join('')}</select></div></header><div class="content">${renderPage()}<footer class="footer"><span><span class="dot"></span>DIVERMANIA · Todo listo para disfrutar</span><span>Control operativo · La factura se emite en tu sistema actual</span></footer></div></main></div>`;
 $('#role-select').onchange=e=>{role=e.target.value;localStorage.setItem('divermania.role',role);page={admin:'overview',cash:'cash',entrance:'times',gamer:'times',kitchen:'orders'}[role];if(role==='entrance')timeTab='park';if(role==='gamer')timeTab='play';render();};
 if(['catalog','inventory','finances'].includes(page)){
 const frame=$('#legacy-frame');frame.addEventListener('load',()=>{try{frame.style.height=Math.max(820,frame.contentDocument.body.scrollHeight)+'px';}catch{}});
 }
 tick();
}
function renderPage(){if(page==='overview')return overview();if(page==='cash')return cashPage();if(page==='times')return timesPage();if(page==='orders')return ordersPage();if(page==='customers')return customersPage();if(page==='screens')return screensPage();if(['catalog','inventory','finances'].includes(page))return legacyPage();return overview();}
function stationCard(station,board=false){const t=active('play').find(t=>t.stationId===station.id),ms=t?remaining(t):0,kind=t?(ms<=0?'expired':ms<=300000?'near':'busy'):'free';return `<article class="station ${kind}" ${t?`data-session="${t.id}"`:''}><div class="station-top"><span>${icon('game')} ${esc(station.name)}</span>${badge(t?(ms<=0?'Finalizado':ms<=300000?'Por terminar':'En uso'):'Disponible',t?(ms<=0?'red':ms<=300000?'orange':'purple'):'')}</div><div class="station-name">${t?(board?'Pase #'+t.number:esc(t.name)):'Lista para la próxima partida'}</div><div class="station-time" ${t?`data-countdown="${t.id}"`:''}>${t?clock(ms):'Libre'}</div><div class="progress"><i ${t?`data-progress="${t.id}"`:''} style="width:${t?Math.min(100,ms/(t.minutes*60000)*100):0}%"></i></div>${board?`<div class="station-footer">${t?`${t.minutes} minutos contratados`:'Disfruta tu próxima partida'}</div>`:t?`<div class="station-footer"><span>Pase #${t.number}</span><button data-action="session-detail" data-id="${t.id}">Ver sesión →</button></div>`:`<button class="free-button" data-action="start-picker" data-id="${station.id}">Asignar pase ${icon('plus')}</button>`}</article>`;}
function alertStrip(){const all=nearSessions();if(!all.length)return '';const first=all[0];const label=first.area==='play'?state.stations.find(x=>x.id===first.stationId)?.name:'Parque · pase #'+first.number;return `<div class="alert-strip">${icon('bell')}<span><strong>${esc(label)} ${remaining(first)<=0?'ha terminado':'está por terminar'}.</strong> ${all.length>1?`Hay ${all.length} sesiones que requieren atención.`:'El encargado puede finalizar la sesión o registrar una ampliación pagada.'}</span><button data-page="times">Ver tiempos →</button></div>`;}
function miniOrder(o){return `<article class="order-mini"><div class="order-line"><div><span class="order-number">#${o.number}</span><span class="order-place">${o.table==='Retiro'?'Para retirar':'Mesa '+esc(o.table)}</span></div>${orderBadge(o)}</div><p>${o.items.map(i=>`${i.qty} × ${esc(i.name)}`).join(' · ')}</p><div class="order-bottom"><span class="age">${icon('clock')} Hace ${ago(o.createdAt)} min</span><button class="btn small ${o.status==='ready'?'success':''}" data-action="order-next" data-id="${o.id}">${o.status==='pending'?'Comenzar preparación':o.status==='preparing'?'Marcar listo':'Confirmar entrega'} ${icon('right')}</button></div></article>`;}
function pendingTicket(t){return `<div class="ticket-row"><div class="ticket-icon ${t.area}">${icon(t.area==='play'?'game':'tree')}</div><div><strong>Pase #${t.number} · ${t.area==='play'?'PlayStation':'Parque infantil'}</strong><p>${esc(t.name)} · ${t.minutes} min · Pago registrado</p></div><button class="btn small" data-action="start-session" data-id="${t.id}">Activar ${icon('right')}</button></div>`;}
function overview(){const playing=active('play').length,park=active('park').length,orders=openOrders();return `${head('Un día para disfrutar.','Aquí tienes todo lo que está pasando en Divermania.',`<button class="btn" data-action="new-order">${icon('plus')} Nuevo pedido</button><button class="btn primary" data-action="new-ticket">${icon('ticket')} Vender pase</button>`)}${notice()}<div class="experience-access"><div><span class="menu-kicker">DESCUBRE LA NUEVA EXPERIENCIA</span><strong>Tu cliente también tiene su propia pantalla.</strong><p>Menú, personalización y seguimiento en una página propia.</p></div><a class="btn primary" href="/cliente.html" target="_blank" rel="noopener">Ver menú del cliente ${icon('right')}</a><a class="btn" href="/televisores.html">Preparar una TV ${icon('screen')}</a></div><div class="stats">${stat('Zona gamer',playing+' <small>/ '+state.stations.length+' estaciones</small>',`<em>${state.stations.length-playing} disponibles</em> para jugar`,'game')}${stat('Parque infantil',park+' <small>/ '+(state.capacity??'aforo por definir')+' cupos</small>','<em>Capacidad disponible</em>','tree','green')}${stat('Pedidos en curso',orders.length,`${orders.filter(o=>o.status==='ready').length} listos para retirar`,'bag','orange')}${stat('Pases por activar',waiting().length,'Pago registrado · Sin iniciar tiempo','ticket','blue')}</div>${alertStrip()}<div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Zona gamer</h2><p>El estado de cada partida, de un vistazo.</p></div><button class="btn text" data-page="times">Ver todo ${icon('right')}</button></div><div class="panel-body"><div class="station-grid">${state.stations.map(s=>stationCard(s)).join('')||empty('Aún no hay estaciones configuradas','Registra las Play que existen en el local.','game')}</div><div class="park-mini"><span class="park-symbol">${icon('tree')}</span><div><strong>El parque también está en marcha</strong><p>${park} ${park===1?'pase activo':'pases activos'} · Control desde la entrada</p></div><span class="park-count">${park}<small> / ${state.capacity??'—'}</small></span></div><div class="legend"><span><i class="dot purple"></i>En uso</span><span><i class="dot orange"></i>Por terminar</span><span><i class="dot"></i>Disponible</span></div></div></section><section class="panel"><div class="panel-head"><div><h2>Pedidos en vivo</h2><p>Del antojo a la cocina.</p></div>${badge(orders.length+' activos','purple')}</div>${orders.length?orders.slice().sort((a,b)=>b.createdAt-a.createdAt).slice(0,3).map(miniOrder).join(''):empty('Todo al día','Los nuevos pedidos aparecerán aquí.','bag')}<div style="padding:8px 20px"><button class="btn text" data-page="orders">Ir a cocina ${icon('right')}</button></div></section></div><div class="bottom-grid"><section class="panel"><div class="panel-head"><div><h2>Listos para comenzar</h2><p>Pases pagados en taquilla, pendientes de activación.</p></div>${badge(waiting().length,'gray')}</div>${waiting().length?waiting().slice(0,3).map(pendingTicket).join(''):empty('Sin pases pendientes','Taquilla puede registrar el siguiente.','ticket')}</section><section class="panel"><div class="panel-head"><h2>A un clic de distancia</h2></div><div class="quick-links"><button class="quick-link" data-action="open-menu">${icon('qr')}<span><strong>Menú para clientes</strong><small>Pedidos desde el teléfono con QR</small></span>${icon('arrow','arrow')}</button><button class="quick-link" data-action="open-board" data-kind="orders">${icon('screen')}<span><strong>Pantalla de pedidos</strong><small>Números listos para retirar</small></span>${icon('arrow','arrow')}</button><button class="quick-link" data-page="customers">${icon('heart')}<span><strong>Quienes siempre vuelven</strong><small>Historial y preferencias de tus clientes</small></span>${icon('arrow','arrow')}</button></div></section></div>`;}
function cashPage(){return `${head('Todo empieza en taquilla.','Registra el pago y entrega un pase. El tiempo se activa en la entrada.',`<button class="btn" data-action="new-order">${icon('bag')} Tomar pedido</button><button class="btn primary" data-action="new-ticket">${icon('plus')} Vender pase</button>`)}${notice()}<div class="stats">${stat('Pases registrados',state.tickets.length,'Parque y PlayStation','ticket')}${stat('Por activar',waiting().length,'Sin consumir minutos','clock','orange')}${stat('Pagos de comida pendientes',state.orders.filter(o=>!o.paymentConfirmed&&o.status!=='cancelled').length,'Confirmar en tu sistema de caja','receipt','blue')}${stat('Clientes guardados',state.customers.length,'Registro con autorización','users','green')}</div><section class="panel"><div class="panel-head"><div><h2>Pases de taquilla</h2><p>Confirmar aquí registra el pago; no procesa un cobro ni emite una factura.</p></div></div><div class="table-scroll"><table><thead><tr><th>Pase / visitante</th><th>Área</th><th>Duración</th><th>Importe</th><th>Comprobante</th><th>Estado</th><th></th></tr></thead><tbody>${state.tickets.slice().reverse().map(t=>`<tr><td><strong>#${t.number}</strong><small>${esc(t.name)}</small></td><td>${t.area==='play'?'PlayStation':'Parque'}</td><td>${t.minutes} min</td><td>${money(t.amount)}</td><td>${esc(t.paymentRef)}</td><td>${badge(t.status==='waiting'?'Por activar':t.status==='active'?'En uso':'Finalizado',t.status==='waiting'?'orange':t.status==='active'?'purple':'gray')}</td><td><button class="btn small" data-action="ticket-detail" data-id="${t.id}">${icon('receipt')} Ver pase</button></td></tr>`).join('')}</tbody></table></div>${!state.tickets.length?empty('Todavía no hay pases','Registra el primer pase en taquilla.','ticket'):''}</section>${voucherList()}<section class="panel gap-top"><div class="panel-head"><h2>Comida · Confirmación de pago</h2></div><div class="table-scroll"><table><thead><tr><th>Pedido</th><th>Importe</th><th>Pago</th><th>Referencia de factura</th><th></th></tr></thead><tbody>${state.orders.filter(o=>o.status!=='cancelled').slice().reverse().map(o=>`<tr><td><strong>#${o.number}</strong><small>${esc(o.name)}</small></td><td>${money(o.total)}</td><td>${badge(o.paymentConfirmed?'Confirmado':'Pendiente',o.paymentConfirmed?'':'orange')}</td><td>${esc(o.invoiceRef)||'—'}</td><td>${!o.paymentConfirmed?`<button class="btn small" data-action="confirm-payment" data-id="${o.id}">Registrar referencia</button>`:''}</td></tr>`).join('')}</tbody></table></div></section>`;}
function timesPage(){return `${head('Cada minuto, bajo control.','La entrada activa los pases pagados y controla los tiempos de parque y Play.',`<button class="btn" data-action="sound">${icon('sound')} ${soundEnabled?'Sonido activado':'Activar alertas'}</button><button class="btn primary" data-action="open-board" data-kind="${timeTab==='play'?'gamer':'park'}">${icon('screen')} Abrir pantalla</button>`)}${notice()}<div class="actions" style="margin-bottom:18px"><button class="btn" data-action="new-station">${icon('plus')} Configurar estación</button><button class="btn" data-action="control-settings">${icon('settings')} Parque y comida incluida</button></div>${alertStrip()}<div class="tabs large"><button class="tab ${timeTab==='play'?'active':''}" data-time-tab="play">PlayStation · ${active('play').length} en uso</button><button class="tab ${timeTab==='park'?'active':''}" data-time-tab="park">Parque infantil · ${active('park').length} en uso</button><button class="tab ${timeTab==='waiting'?'active':''}" data-time-tab="waiting">Por activar · ${waiting().length}</button></div>${timeTab==='play'?`<div class="station-grid wide">${state.stations.map(s=>stationCard(s)).join('')||empty('Aún no hay estaciones configuradas','Registra las Play que existen en el local.','game')}</div>`:timeTab==='park'?`<section class="panel"><div class="panel-head"><h2>Parque infantil</h2>${badge(active('park').length+' / '+(state.capacity??'sin definir')+' cupos','purple')}</div><div class="table-scroll"><table><thead><tr><th>Pase</th><th>Adulto responsable</th><th>Tiempo contratado</th><th>Tiempo restante</th><th></th></tr></thead><tbody>${active('park').map(t=>`<tr><td><strong>#${t.number}</strong></td><td>${esc(t.name)}</td><td>${t.minutes} min</td><td><strong data-countdown="${t.id}">${clock(remaining(t))}</strong></td><td><button class="btn small" data-action="session-detail" data-id="${t.id}">Gestionar</button></td></tr>`).join('')}</tbody></table></div>${active('park').length?'':empty('El parque está listo','Activa un pase cuando comience la visita.','tree')}</section>`:`<section class="panel"><div class="panel-head"><h2>Pases pagados pendientes de activación</h2></div>${waiting().length?waiting().map(pendingTicket).join(''):empty('Todo activado','Los pases nuevos aparecerán aquí.','ticket')}</section>`}<div class="banner-info gap-top"><strong>El reloj comienza al activar el pase.</strong> Una sesión vencida sigue ocupando su estación hasta que el encargado confirma la salida. Las ampliaciones requieren un nuevo pago confirmado en taquilla.</div>`;}
function kitchenCard(o){return `<article class="order-card"><div class="order-line"><span class="order-number">#${o.number}</span>${badge(o.table==='Retiro'?'Retiro':'Mesa '+o.table,'gray')}</div>${o.inventoryStatus==='partial'?'<div class="order-notes">Hay productos con receta o cantidades pendientes de configurar.</div>':''}<div class="order-items">${o.items.map(i=>`<div>${i.qty} × ${esc(i.name)}${i.removed?.length?`<small>Sin: ${esc(i.removed.join(', '))}</small>`:''}</div>`).join('')}</div>${o.notes?`<p class="order-notes">${esc(o.notes)}</p>`:''}<div class="status-line"><span>${ago(o.createdAt)} min desde el pedido</span><span>${money(o.total)}</span></div><button class="btn ${o.status==='ready'?'success':'primary'}" data-action="order-next" data-id="${o.id}">${o.status==='pending'?'Comenzar preparación':o.status==='preparing'?'Listo para retirar':'Confirmar entrega'} ${icon('right')}</button><button class="cancel-btn" data-action="order-detail" data-id="${o.id}">Ver detalle y seguimiento</button></article>`;}
function ordersPage(){return `${head('La cocina tiene el control.','Cada pedido con sus ingredientes, observaciones y estado en vivo.',`<button class="btn" data-action="open-board" data-kind="orders">${icon('screen')} Pantalla de turnos</button><button class="btn primary" data-action="new-order">${icon('plus')} Pedido manual</button>`)}${notice()}<div class="section-tools"><div class="tabs"><button class="tab ${orderTab==='kitchen'?'active':''}" data-order-tab="kitchen">Vista cocina</button><button class="tab ${orderTab==='all'?'active':''}" data-order-tab="all">Todos los pedidos</button></div><button class="btn text" data-action="legacy" data-tab="manual">Abrir pedido manual original ${icon('external')}</button></div>${orderTab==='kitchen'?`<div class="kanban">${['pending','preparing','ready'].map(status=>`<section class="kanban-col"><div class="kanban-title">${orderLabels[status]} <span>${state.orders.filter(o=>o.status===status).length}</span></div>${state.orders.filter(o=>o.status===status).sort((a,b)=>a.createdAt-b.createdAt).map(kitchenCard).join('')||empty('Sin pedidos aquí','Se actualizará al cambiar el estado.','bag')}</section>`).join('')}</div>`:`<section class="panel"><div class="table-scroll"><table><thead><tr><th>Pedido</th><th>Cliente / ubicación</th><th>Total</th><th>Estado</th><th>Pago</th><th></th></tr></thead><tbody>${state.orders.slice().reverse().map(o=>`<tr><td><strong>#${o.number}</strong><small>${formatDate(o.createdAt)}</small></td><td>${esc(o.name)}<small>${o.table==='Retiro'?'Retiro':'Mesa '+esc(o.table)}</small></td><td>${money(o.total)}</td><td>${orderBadge(o)}</td><td>${badge(o.paymentConfirmed?'Confirmado':'Pendiente',o.paymentConfirmed?'':'orange')}</td><td><button class="btn small" data-action="order-detail" data-id="${o.id}">Ver pedido</button></td></tr>`).join('')}</tbody></table></div></section>`}`;}
function customerStats(c){const orders=state.orders.filter(o=>o.customerId===c.id&&o.status!=='cancelled'),tickets=state.tickets.filter(t=>t.customerId===c.id);const dates=new Set([...orders.map(o=>new Date(o.createdAt).toLocaleDateString('es-VE',{timeZone:'America/Caracas'})),...tickets.map(t=>new Date(t.createdAt).toLocaleDateString('es-VE',{timeZone:'America/Caracas'}))]);return {visits:dates.size,total:orders.filter(o=>o.paymentConfirmed).reduce((a,o)=>a+o.total,0)+tickets.reduce((a,t)=>a+t.amount,0),orders,tickets};}
function customersPage(){const list=state.customers.filter(c=>(c.name+' '+c.phone).toLowerCase().includes(search.toLowerCase()));return `${head('Qué bueno verte de nuevo.','Una ficha por cliente. Cada compra y cada visita quedan relacionadas.',`<button class="btn primary" data-action="new-customer">${icon('plus')} Guardar cliente</button>`)}${notice()}<div class="section-tools"><div class="search">${icon('search')}<input id="customer-search" placeholder="Buscar por nombre o teléfono" value="${esc(search)}" aria-label="Buscar cliente"></div><span class="connection-pill">${icon('users')} ${state.customers.length} clientes guardados</span></div><div class="customer-grid">${list.map(c=>{const s=customerStats(c);return `<article class="customer-card"><div class="customer-head"><span class="avatar">${esc(initials(c.name))}</span><div><h3>${esc(c.name)}</h3><p>${esc(c.phone)}</p></div></div><div class="customer-stats"><div><strong>${s.visits}</strong><small>Días con actividad</small></div><div><strong>${money(s.total)}</strong><small>Pagos registrados</small></div></div><div class="order-line">${badge(c.promotions?'Acepta promociones':'Solo historial',c.promotions?'':'gray')}<button class="btn text" data-action="customer-detail" data-id="${c.id}">Ver ficha →</button></div></article>`;}).join('')||empty('No encontramos clientes','Puedes crear una ficha con su autorización.','users')}</div><div class="banner-info gap-top">Guardar el historial y recibir promociones son decisiones separadas. No se crean fichas automáticamente al hacer un pedido. ${preview?'Los números de esta vista son ficticios.':''}</div>`;}
function screenLink(kind){return `${location.origin}/?view=board&kind=${kind}`;}
function screenProfiles(){return preview?[]:(state.devices||[]);}
const screenNames={orders:'Pedidos y turnos',gamer:'Tiempos de Play',park:'Tiempos del parque'};
function screenUrl(kind,name=''){return `${location.origin}/?view=board&kind=${encodeURIComponent(kind)}${name?'&device='+encodeURIComponent(name):''}`;}
function screenWizard(){modal('Vincular un televisor',`<form id="screen-form"><div class="field"><label for="screen-name">Nombre del dispositivo</label><input id="screen-name" name="screenName" required maxlength="50" placeholder="Ej. TV de la zona gamer"></div><div class="field"><label for="screen-kind">Función de la pantalla</label><select id="screen-kind" name="screenKind"><option value="orders">Pedidos en preparación y listos</option><option value="gamer">Estaciones y tiempos de Play</option><option value="park">Pases y tiempos del parque</option></select></div><p class="form-note">Obtendrás un código de un solo uso, válido por 10 minutos. En la TV abre el enlace e introduce el código.</p><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Volver</button><button class="btn primary" type="submit">Generar código</button></div></form>`);const f=$('#screen-form');f.onsubmit=e=>{e.preventDefault();submit(f,async()=>{const r=await execute('device.prepare',{name:f.screenName.value,kind:f.screenKind.value});showPreparedScreen(r);});};}
function showPreparedScreen(profile){const url=screenUrl(profile.kind);modal('Activa tu pantalla',`<div class="prepared-screen-head">${icon('screen')}<div><h3>${esc(profile.name)}</h3><p>${screenNames[profile.kind]}</p></div></div><div class="device-code">${esc(profile.code||'Código utilizado')}</div><p class="form-note">${profile.preview?'Esta es una vista previa. El código de prueba no vincula una TV física.':profile.code?'Código de un solo uso · Válido 10 minutos.':'Para volver a vincularla genera un nuevo código.'}</p><div class="qr-box" id="prepared-screen-qr"></div><div class="qr-link">${esc(url)}</div><p class="form-note">Abre este enlace en el navegador del televisor, o en una computadora/TV Box conectada por HDMI. Introduce el código, activa pantalla completa y sonido.</p><div class="modal-actions"><button class="btn" data-action="copy-link" data-url="${esc(url)}">Copiar enlace</button><a class="btn primary" href="${esc(url)}" target="_blank" rel="noopener">Abrir pantalla</a></div>`);makeQR('prepared-screen-qr',url);}
function screensPage(){const profiles=screenProfiles();return `${head('TU LOCAL, EN PANTALLA.','Elige qué ve cada televisor y prepara su enlace en tres pasos.',`<a class="btn" href="/cliente.html" target="_blank" rel="noopener">${icon('bag')} Ver menú del cliente</a><button class="btn primary" data-action="screen-wizard">${icon('plus')} Vincular pantalla</button>`)}
 <div class="screens-intro"><div><span class="menu-kicker">UNA VISTA PARA CADA ÁREA</span><h2>EL PEDIDO AVANZA.<br><em>LA DIVERSIÓN SIGUE.</em></h2><p>Turnos para quienes esperan su comida. Tiempos para quienes siguen jugando. Cada pantalla muestra justo lo que necesita.</p></div><div class="screens-illustration" aria-hidden="true"><div class="mini-tv"><span>LISTOS PARA RETIRAR</span><strong>102 <i>✦</i></strong><div></div></div><span class="screens-spark">✦</span></div></div>
 <div class="screen-connection-status">${icon('link')}<div><strong>${preview?'Vista previa local':'Sincronización con Firebase'}</strong><p>${preview?'Esta vista no vincula equipos reales.':'Las pantallas se autorizan con un código de un solo uso. El servicio de vinculación debe estar publicado en Firebase.'}</p></div><button class="btn small" data-action="screen-guide">Ver cómo se conecta ${icon('right')}</button></div>
 <div class="screen-setup-flow"><div><span>01</span><strong>Elige su función</strong><p>Pedidos, Play o parque.</p></div><div><span>02</span><strong>Prepara el enlace</strong><p>Asigna un nombre a la pantalla.</p></div><div><span>03</span><strong>Ábrelo en la TV</strong><p>Usa navegador o un equipo HDMI.</p></div></div>
 <div class="device-grid">${[['orders','bag','Pantalla de pedidos','Solo números de turno. Cada pedido pasa de preparación a listo para retirar.'],['gamer','game','Pantalla gamer','Estaciones disponibles, minutos restantes y avisos al terminar una partida.'],['park','tree','Pantalla del parque','Pases activos identificados por número y tiempo disponible para disfrutar.']].map(([kind,i,title,desc])=>`<article class="device-card screen-style-${kind}"><div class="device-preview"><span class="screen-preview-caption">${kind==='orders'?'VISTA PREVIA · PEDIDOS':kind==='gamer'?'VISTA PREVIA · GAMER':'VISTA PREVIA · PARQUE'}</span>${kind==='orders'?'<strong class="screen-big-turn">102 <span>LISTO ✓</span></strong>':kind==='gamer'?'<strong class="screen-big-turn">PLAY 01 <span>04:45</span></strong>':'<strong class="screen-big-turn">PASE 43 <span>16:00</span></strong>'}</div><h3>${icon(i)} ${title}</h3><p>${desc}</p><button class="btn primary" data-action="open-board" data-kind="${kind}">${icon('external')} Ver esta pantalla</button><button class="btn" data-action="copy-link" data-url="${esc(screenLink(kind))}">${icon('link')} Copiar enlace</button><button class="btn text" data-action="screen-qr" data-kind="${kind}">${icon('qr')} Mostrar QR</button></article>`).join('')}</div>
 ${profiles.length?`<section class="panel gap-top"><div class="panel-head"><div><h2>Dispositivos vinculados</h2><p>La conexión se confirma mediante un latido del dispositivo cada minuto.</p></div>${badge(profiles.length+' dispositivos','orange')}</div>${profiles.map(p=>`<div class="prepared-screen-row"><span class="ticket-icon">${icon('screen')}</span><div><strong>${esc(p.name)}</strong><p>${screenNames[p.kind]} · ${p.revoked?'Desvinculado':Date.now()-p.lastSeen<120000?'Conectado recientemente':'Sin señal reciente'}</p></div><button class="btn small" data-action="prepared-screen" data-id="${esc(p.id)}">Ver enlace</button><button class="icon-btn" aria-label="Quitar enlace de ${esc(p.name)}" data-action="revoke-screen" data-id="${esc(p.id)}">${icon('close')}</button></div>`).join('')}</section>`:''}
 <section class="tv-help-grid gap-top"><article class="panel"><div class="panel-head"><h2>${icon('screen')} ¿Qué necesita el televisor?</h2></div><div class="panel-body help-list"><p><strong>Smart TV con navegador:</strong> abre el enlace y activa pantalla completa y sonido.</p><p><strong>TV sin navegador:</strong> conecta una computadora, mini PC o TV Box por HDMI y abre el enlace allí.</p><p><strong>Televisor de la Play:</strong> esta versión usa una pantalla compartida de tiempos. No coloca un aviso encima del juego que entra por HDMI.</p></div></article><article class="panel"><div class="panel-head"><h2>${icon('qr')} También hay una vista para el cliente</h2></div><div class="panel-body help-list"><p>El menú tiene su propia página con fotos, categorías, personalización, carrito y seguimiento.</p><a class="btn primary full-width" href="/cliente.html" target="_blank" rel="noopener">Ver la experiencia del cliente ${icon('right')}</a><button class="btn full-width gap-top" data-action="show-qr">${icon('qr')} Generar QR por mesa</button></div></article></section>`;}
function screenGuide(){modal('Cómo enlazaremos los dispositivos',`<div class="help-list"><p><strong>1. Publicar el código.</strong> GitHub guarda tus archivos; Cloudflare Pages publica la aplicación y genera su dirección.</p><p><strong>2. Conectar Firebase.</strong> La computadora de caja, la entrada, cocina y las pantallas reciben los cambios desde la misma base de datos. Compartir wifi o un enlace no sustituye esa conexión.</p><p><strong>3. Autorizar al equipo.</strong> En producción asignaremos permisos de caja, entrada, gamer y cocina; los televisores verán únicamente sus datos operativos.</p><p><strong>4. Abrir la vista en la TV.</strong> Desde el navegador del televisor o un equipo conectado por HDMI. El sonido se activa con una interacción en cada dispositivo.</p><p><strong>Puesta en marcha:</strong> la vinculación, las cuentas del equipo y las operaciones protegidas requieren publicar los servicios y reglas de Firebase incluidos en el repositorio.</p></div><button class="btn primary full-width gap-top" data-action="screen-wizard">Preparar una pantalla ${icon('right')}</button>`);}

function legacyPage(){const tab={catalog:'catalogo',inventory:'inventario',finances:'finanzas'}[page];return `${head(pageTitles[page],'Catálogo, recetas, inventario y finanzas del sistema existente.',`<button class="btn" data-action="legacy" data-tab="${tab}">${icon('external')} Abrir en otra pestaña</button>`)}${notice()}${page==='catalog'?`<button class="btn primary gap-top" style="margin-bottom:18px" data-action="import-menu">Cargar menú del PDF ${icon('plus')}</button>`:''}<div class="banner-info"><strong>Conservamos las funciones existentes.</strong> ${preview?'Los cambios de esta vista se guardan solo como prueba.':'Los datos se guardan en el mismo proyecto Firebase. Los permisos se verifican con tu cuenta.'} Configura las cantidades exactas de cada receta antes de esperar descuentos completos de inventario.</div><div class="panel"><iframe id="legacy-frame" title="${esc(pageTitles[page])} · módulo original en demostración" src="/gestion.html?tab=${tab}" style="width:100%;height:900px;border:0;display:block"></iframe></div>`;}
function modal(title,body,wide=false){closeModal();$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${title}</h2><button class="close" aria-label="Cerrar" data-action="close-modal">${icon('close')}</button></div><div class="modal-body"><div class="error-message" id="form-error" role="alert"></div>${body}</div></section></div>`;setTimeout(()=>$('#modal-root input:not([type=checkbox]),#modal-root select,#modal-root button')?.focus(),40);}
function closeModal(){modalCloseHook?.();modalCloseHook=null;$('#modal-root').innerHTML='';}
function formError(err){const el=$('#form-error');if(el){el.textContent=err.message||err;el.classList.add('show');}else toast(err.message||err,true);}
function toast(message,error=false){$('#toast-root').innerHTML=`<div class="toast ${error?'error':''}" role="status">${esc(message)}</div>`;setTimeout(()=>$('#toast-root').innerHTML='',4000);}
async function submit(form,task){const button=form.querySelector('button[type=submit]');if(button)button.disabled=true;try{await task();}catch(err){formError(err);}finally{if(button)button.disabled=false;}}
function customerOptions(){return `<option value="">Visitante sin ficha</option>${state.customers.map(c=>`<option value="${c.id}">${esc(c.name)} · ${esc(c.phone)}</option>`).join('')}`;}
function newTicket(){const requestKey=uid();modal('Vender pase en taquilla',`<form id="ticket-form"><div class="form-grid"><div class="field"><label for="ticket-area">Área</label><select id="ticket-area" name="area"><option value="play">PlayStation</option><option value="park">Parque infantil</option></select></div><div class="field"><label for="ticket-minutes">Tiempo contratado</label><select id="ticket-minutes" name="minutes">${packages.play.map(p=>`<option value="${p.minutes}">${packageLabel(p)}</option>`).join('')}</select></div></div><div class="field"><label for="ticket-customer">Cliente frecuente · opcional</label><select id="ticket-customer" name="customerId">${customerOptions()}</select></div><div class="field"><label for="ticket-name">Nombre / adulto responsable</label><input id="ticket-name" name="name" required maxlength="100" placeholder="¿A nombre de quién?" autocomplete="name"></div><div class="field"><label for="ticket-ref">Referencia o comprobante de taquilla</label><input id="ticket-ref" name="paymentRef" required placeholder="Ej. ticket de caja 0248" maxlength="100"></div><div class="total-box"><span>Importe del paquete</span><strong id="ticket-total">${money(rates.play[30])}</strong></div><label class="check-line"><input type="checkbox" name="paid" required><span>Confirmo que el pago ya fue recibido en taquilla.</span></label><p class="form-note">Se emitirá un pase sin iniciar el reloj. La factura se hace en el sistema actual. Tarifas informadas por Divermanía. El control adicional queda pendiente de definir por sesión o bloque.</p><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Cancelar</button><button class="btn primary" type="submit">${icon('ticket')} Emitir pase</button></div></form>`);
 const f=$('#ticket-form');const total=()=>$('#ticket-total').textContent=money(rates[f.area.value][f.minutes.value]);f.area.onchange=()=>{f.minutes.innerHTML=packages[f.area.value].map(p=>`<option value="${p.minutes}">${packageLabel(p)}</option>`).join('');total();};f.minutes.onchange=total;total();f.customerId.onchange=()=>{const c=state.customers.find(c=>c.id===f.customerId.value);if(c)f.elements.name.value=c.name;};f.onsubmit=e=>{e.preventDefault();submit(f,async()=>{const r=await execute('ticket.create',{area:f.area.value,minutes:Number(f.minutes.value),name:f.elements.name.value,customerId:f.customerId.value||null,paymentRef:f.paymentRef.value,paymentConfirmed:f.paid.checked},requestKey);state=readState();ticketDetail(r.id);toast('Pase emitido. El tiempo aún no ha comenzado.');});};}
function ticketDetail(id){const t=state.tickets.find(t=>t.id===id);if(!t)return;modal('Pase de taquilla',`<div class="ticket-print"><div class="eyebrow">DIVERMANIA · CONTROL OPERATIVO</div><div class="ticket-no">#${t.number}</div><h3>${t.area==='play'?'PlayStation':'Parque infantil'} · ${t.minutes} minutos</h3><p>${esc(t.name)}</p><p>Pago registrado · ${esc(t.paymentRef)}</p><p>${formatDate(t.createdAt)}</p><div class="qr-box" id="ticket-qr" style="width:160px;height:160px"></div><p>${t.status==='waiting'?'Presenta este pase en la entrada para activar el tiempo.':t.status==='active'?'Pase activado.':'Sesión finalizada.'}</p><p><strong>Control interno · No es una factura</strong></p></div><div class="modal-actions"><button class="btn" data-action="print">${icon('print')} Imprimir</button>${t.status==='waiting'?`<button class="btn primary" data-action="start-session" data-id="${t.id}">Activar en entrada</button>`:''}</div>`);makeQR('ticket-qr',`${location.origin}/?page=times&ticket=${encodeURIComponent(t.id)}`,124);}
function startPicker(stationId){const list=waiting().filter(t=>t.area==='play');modal('Asignar pase a una Play',list.length?`<p class="form-note" style="margin-bottom:16px">Selecciona un pase pagado para esta estación.</p>${list.map(t=>`<div class="ticket-row"><div><strong>#${t.number} · ${esc(t.name)}</strong><p>${t.minutes} minutos</p></div><button class="btn primary small" data-action="start-session" data-id="${t.id}" data-station="${stationId}">Seleccionar</button></div>`).join('')}`:`${empty('No hay pases de Play pendientes','Registra el pago en taquilla para emitir uno.','ticket')}<button class="btn primary full-width" data-action="new-ticket">Vender pase</button>`);}
function startSession(id,stationId=''){const t=state.tickets.find(t=>t.id===id);if(!t||t.status!=='waiting')return toast('Este pase ya no está pendiente.',true);const available=state.stations.filter(s=>s.enabled!==false&&!active('play').some(t=>t.stationId===s.id));modal('Activar tiempo en la entrada',`<form id="start-form"><div class="total-box"><span>Pase #${t.number} · ${esc(t.name)}</span><strong>${t.minutes} min</strong></div>${t.area==='play'?`<div class="field"><label for="start-station">Estación disponible</label><select name="stationId" id="start-station" required><option value="">Selecciona una Play</option>${available.map(s=>`<option value="${s.id}" ${stationId===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div>`:`<div class="banner-info">Parque infantil · ${active('park').length} de ${state.capacity??'—'} cupos ocupados. Cada pase representa un ingreso.</div>`}<p class="form-note">El reloj comenzará al confirmar. El pago de este pase ya fue registrado en taquilla.</p><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Cancelar</button><button class="btn primary" type="submit">${icon('clock')} Comenzar ${t.minutes} minutos</button></div></form>`);const f=$('#start-form');f.onsubmit=e=>{e.preventDefault();submit(f,async()=>{await execute('session.start',{id,stationId:f.stationId?.value||null});closeModal();toast('Tiempo activado. ¡A disfrutar!');});};}
function sessionDetail(id){const t=state.tickets.find(t=>t.id===id);if(!t)return;modal('Sesión · pase #'+t.number,`<div class="ticket-print"><div class="eyebrow">${t.area==='play'?esc(state.stations.find(s=>s.id===t.stationId)?.name):'PARQUE INFANTIL'}</div><div class="ticket-no" style="font-size:48px" data-countdown="${t.id}">${clock(remaining(t))}</div><h3>${esc(t.name)}</h3><p>${t.minutes} minutos contratados · Pago registrado</p><p>Finaliza ${new Date(t.endAt).toLocaleTimeString('es-VE',{timeZone:'America/Caracas',hour:'2-digit',minute:'2-digit'})}</p></div><div class="modal-actions" style="justify-content:center"><button class="btn" data-action="acknowledge" data-id="${t.id}">${icon('bell')} Reconocer alerta</button><button class="btn primary" data-action="extend" data-id="${t.id}">${icon('plus')} Ampliar</button></div><button class="btn danger full-width gap-top" data-action="finish-session" data-id="${t.id}">Confirmar salida y finalizar sesión</button><p class="form-note">Finalizar libera la estación o el cupo del parque.</p>`);}
function extendSession(id){const requestKey=uid();const t=state.tickets.find(t=>t.id===id);modal('Ampliación pagada en taquilla',`<form id="extend-form"><div class="field"><label for="extend-minutes">Minutos adicionales</label><select id="extend-minutes" name="minutes">${packages[t.area].map(p=>`<option value="${p.minutes}">${packageLabel(p)} · ${money(p.price)}</option>`).join('')}</select></div><div class="field"><label for="extend-ref">Referencia de pago de taquilla</label><input name="paymentRef" id="extend-ref" required maxlength="100" placeholder="Comprobante de la ampliación"></div><label class="check-line"><input type="checkbox" name="paid" required><span>El pago de esta ampliación ya fue recibido en taquilla.</span></label><p class="form-note">Si el tiempo ya venció, la ampliación comenzará desde ahora.</p><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Cancelar</button><button class="btn primary" type="submit">Confirmar ampliación</button></div></form>`);const f=$('#extend-form');f.onsubmit=e=>{e.preventDefault();submit(f,async()=>{await execute('session.extend',{id,minutes:Number(f.minutes.value),paymentRef:f.paymentRef.value,paymentConfirmed:f.paid.checked},requestKey);acknowledged.delete(id);closeModal();toast('Tiempo ampliado y actualizado.');});};}
function customerForm(){modal('Guardar cliente frecuente',`<form id="customer-form"><div class="field"><label for="customer-name">Nombre</label><input name="name" id="customer-name" required autocomplete="name" maxlength="100" placeholder="Nombre del cliente"></div><div class="field"><label for="customer-phone">Teléfono con código de país</label><input name="phone" id="customer-phone" type="tel" required placeholder="Ej. 584121234567" autocomplete="tel"></div><label class="check-line"><input type="checkbox" name="consent" required><span>El cliente acepta guardar sus datos e historial para identificar sus próximas visitas.</span></label><label class="check-line"><input type="checkbox" name="promotions"><span>También acepta recibir promociones. Es opcional y puede cambiar de opinión.</span></label><p class="form-note">Si el teléfono ya está registrado, se actualizará su ficha sin duplicarla. ${preview?'Esta vista guarda datos solo en el navegador; usa información ficticia.':'La ficha se guarda en Firebase y se consulta solo con una cuenta del equipo.'}</p><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Cancelar</button><button class="btn primary" type="submit">Guardar ficha</button></div></form>`);const f=$('#customer-form');f.onsubmit=e=>{e.preventDefault();submit(f,async()=>{const r=await execute('customer.save',{name:f.elements.name.value,phone:f.phone.value,consent:f.consent.checked,promotions:f.promotions.checked});closeModal();toast(r.existing?'Ficha actualizada sin duplicar el cliente.':'Cliente guardado.');});};}
function customerDetail(id){const c=state.customers.find(c=>c.id===id),s=customerStats(c);const history=[...s.orders.map(o=>({at:o.createdAt,text:`Pedido #${o.number} · ${orderLabels[o.status]}`,amount:o.total})),...s.tickets.map(t=>({at:t.createdAt,text:`${t.area==='play'?'PlayStation':'Parque'} · ${t.minutes} min · Pase #${t.number}`,amount:t.amount}))].sort((a,b)=>b.at-a.at);modal('Ficha del cliente',`<div class="customer-head"><span class="avatar">${esc(initials(c.name))}</span><div><h3>${esc(c.name)}</h3><p>${esc(c.phone)}</p></div></div><div class="customer-stats"><div><strong>${s.visits}</strong><small>Días con actividad registrada</small></div><div><strong>${money(s.total)}</strong><small>Pagos registrados</small></div></div>${badge(c.promotions?'Acepta promociones':'Sin autorización para promociones',c.promotions?'':'gray')}<h3 class="gap-top">Historial</h3>${history.length?history.map(h=>`<div class="activity-row">${icon('receipt')}<span>${esc(h.text)}<br><small style="margin:0">${formatDate(h.at)}</small></span><small>${money(h.amount)}</small></div>`).join(''):empty('Aún no tiene actividad','Asocia el siguiente pase o pedido a su ficha.','heart')}<p class="form-note">Este historial refleja operaciones registradas, no valida pagos bancarios ni sustituye la contabilidad.</p>`);}
function confirmPayment(id){modal('Registrar pago y referencia externa',`<form id="payment-form"><p class="form-note" style="margin:0 0 18px">Primero realiza el cobro y la factura en el sistema de caja. Luego registra su referencia para relacionar ambos sistemas.</p><div class="field"><label for="invoice-ref">Número de factura o referencia de caja</label><input id="invoice-ref" name="invoiceRef" required maxlength="100" placeholder="Ej. factura 005624"></div><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Cancelar</button><button class="btn primary" type="submit">Pago confirmado en caja</button></div></form>`);const f=$('#payment-form');f.onsubmit=e=>{e.preventDefault();submit(f,async()=>{await execute('order.payment',{id,invoiceRef:f.invoiceRef.value});closeModal();toast('Referencia registrada.');});};}
function orderDetail(id){const o=state.orders.find(o=>o.id===id);if(!o)return;const url=`${location.origin}/seguimiento.html?token=${encodeURIComponent(o.token)}`;modal('Pedido #'+o.number,`<div class="order-line">${orderBadge(o)}<strong>${money(o.total)}</strong></div><p class="form-note">${esc(o.name)} · ${o.table==='Retiro'?'Retiro':'Mesa '+esc(o.table)} · ${formatDate(o.createdAt)}</p>${o.inventoryStatus==='partial'?'<div class="order-notes">Hay productos con receta o cantidades pendientes de configurar.</div>':''}<div class="order-items">${o.items.map(i=>`<div>${i.qty} × ${esc(i.name)}${i.removed?.length?`<small>Sin: ${esc(i.removed.join(', '))}</small>`:''}</div>`).join('')}</div>${o.notes?`<p class="order-notes">${esc(o.notes)}</p>`:''}<div class="total-box"><span>Pago en sistema de caja</span>${badge(o.paymentConfirmed?'Confirmado':'Pendiente',o.paymentConfirmed?'':'orange')}</div>${o.invoiceRef?`<p class="form-note">Referencia: ${esc(o.invoiceRef)}</p>`:''}<div class="actions"><a class="btn" target="_blank" rel="noopener" href="${esc(url)}">${icon('external')} Ver seguimiento</a><button class="btn" data-action="copy-link" data-url="${esc(url)}">${icon('link')} Copiar enlace</button><button class="btn" data-action="print-order" data-id="${o.id}">${icon('print')} Turno sin teléfono</button></div><div class="field gap-top"><label for="assign-customer">Asociar a cliente frecuente · opcional</label><div class="actions"><select id="assign-customer" style="flex:1">${customerOptions()}</select><button class="btn" data-action="assign-customer" data-id="${o.id}">Guardar vínculo</button></div></div><div class="modal-actions">${!o.paymentConfirmed&&o.status!=='cancelled'?`<button class="btn" data-action="confirm-payment" data-id="${o.id}">Registrar pago</button>`:''}${['pending','preparing','ready'].includes(o.status)?`<button class="btn danger" data-action="cancel-order" data-id="${o.id}">Cancelar pedido</button>`:''}</div>`);}
function printOrder(id){const o=state.orders.find(o=>o.id===id);modal('Turno para retirar',`<div class="ticket-print"><div class="eyebrow">DIVERMANIA · TU PEDIDO</div><div class="ticket-no">#${o.number}</div><h3>Este es tu número de turno</h3><p>Cuando aparezca en “Listos para retirar”,<br>acércate al área de entrega.</p><p>${o.table==='Retiro'?'Retiro en mostrador':'Mesa '+esc(o.table)}</p><p>Control interno · No es una factura</p></div><div class="modal-actions"><button class="btn primary" data-action="print">${icon('print')} Imprimir turno</button></div>`);}
function makeQR(id,url,size=180){const el=document.getElementById(id);if(el&&window.QRCode){el.innerHTML='';new window.QRCode(el,{text:url,width:size,height:size,colorDark:'#22283c',colorLight:'#ffffff',correctLevel:window.QRCode.CorrectLevel.M});}else if(el)el.textContent='El generador QR no pudo cargar. Puedes copiar el enlace.';}
function qrModal(kind='menu'){const isMenu=kind==='menu';const url=isMenu?`${location.origin}/cliente.html?mesa=1`:screenLink(kind);modal(isMenu?'QR del menú por mesa':'QR de la pantalla',`${isMenu?`<div class="field"><label for="qr-table">Mesa</label><select id="qr-table"><option value="">Sin mesa · Retiro / Delivery</option>${Array.from({length:10},(_,i)=>`<option value="${i+1}" ${i===0?'selected':''}>Mesa ${i+1}</option>`).join('')}</select></div>`:''}<div class="qr-box" id="main-qr"></div><div class="qr-link" id="qr-url">${esc(url)}</div><p class="form-note">${preview?'Este QR abre una revisión con datos de prueba.':'Este enlace abre el menú conectado a tu Firebase.'}</p><div class="modal-actions"><button class="btn" data-action="print">${icon('print')} Imprimir</button><button class="btn primary" id="copy-qr">${icon('link')} Copiar enlace</button></div>`);let current=url;makeQR('main-qr',current);if(isMenu)$('#qr-table').onchange=e=>{current=`${location.origin}/cliente.html${e.target.value?'&mesa='+encodeURIComponent(e.target.value):''}`;$('#qr-url').textContent=current;makeQR('main-qr',current);};$('#copy-qr').onclick=()=>copy(current);}
async function copy(value){try{await navigator.clipboard.writeText(value);toast('Enlace copiado.');}catch{modal('Copiar enlace',`<div class="field"><label>Selecciona y copia el enlace</label><input id="manual-copy" readonly value="${esc(value)}"></div>`);$('#manual-copy').select();}}
function oldManualOrder(){modal('Pedido manual · Sin teléfono del cliente',`<div class="help-list"><p>El personal puede tomar el pedido desde el módulo original, sin exigir teléfono al visitante: incluye productos, modificadores, observaciones, mesa o delivery y mensaje de WhatsApp.</p><p>El pedido aparecerá en la cocina y recibirá un número de turno. El cliente puede esperar su número en la pantalla sin llevar teléfono.</p></div><div class="modal-actions"><button class="btn" data-action="close-modal">Cerrar</button><button class="btn primary" data-action="legacy" data-tab="manual">Abrir formulario original ${icon('external')}</button></div>`);}
function help(){modal('Cómo funciona Divermanía',`<div class="help-list"><p><strong>1. Taquilla.</strong> Emite un pase y registra ${preview?'un comprobante ficticio':'el comprobante de taquilla'}. El reloj todavía no empieza.</p><p><strong>2. Entrada.</strong> Ve a “Parque y Play → Por activar”, asigna una estación y comienza el tiempo.</p><p><strong>3. Cocina.</strong> Abre el menú en otra pestaña, envía un pedido y cambia su estado desde cocina.</p><p><strong>4. Pantallas.</strong> Abre los tableros de turnos y tiempos en pestañas del mismo navegador.</p><p><strong>5. Sistema actual.</strong> Catálogo, inventario y finanzas conservan tus módulos originales con datos ficticios.</p><p>${preview?'Esta vista previa no escribe en tu Firebase real.':'La sincronización utiliza Firebase. Los avisos con la página cerrada requieren Web Push o una integración oficial de WhatsApp.'}</p></div><button class="btn primary full-width gap-top" data-action="close-modal">Vamos a probar</button>`);}
function readClientCart(){try{const cart=JSON.parse(localStorage.getItem('divermania.client.cart.v1')||'[]');return Array.isArray(cart)?cart.filter(x=>typeof x.productId==='string'&&Number.isInteger(x.qty)&&x.qty>=1&&x.qty<=20&&Array.isArray(x.removed)).slice(0,30):[];}catch{return [];}}
function saveClientCart(){localStorage.setItem('divermania.client.cart.v1',JSON.stringify(cart));}
function clientBrand(){return `<a class="client-brand" href="/" aria-label="Divermanía · Inicio"><img src="/logodivermania.png" alt="Divermanía" class="client-logo"><span>COMIDA<br><b>Y DIVERSIÓN.</b></span></a>`;}
const foodPhoto=p=>p.image||({burger:'/assets/burger.jpg',hotdog:'/assets/hotdog.jpg',fries:'/assets/fries.jpg',juice:'/assets/juice.jpg',water:'/assets/water.jpg'}[p.id]||'');
const categorySymbol=c=>({'Todos':'✦','Hamburguesas':'🍔','Perros':'🌭','Fiesta':'🎉','Acompañantes':'🍟','Bebidas':'🥤'}[c]||'🍽️');
function renderMenu(){
 cart=cart.filter(item=>state.catalog.some(p=>p.id===item.productId));saveClientCart();
 const mesa=params.get('mesa'),lastToken=localStorage.getItem('divermania.lastToken');
 const categories=['Todos',...new Set(state.catalog.map(p=>p.category))];
 const filtered=state.catalog.filter(p=>p.enabled!==false&&(menuCat==='Todos'||p.category===menuCat)&&(!foodSearch||(p.name+' '+p.description).toLowerCase().includes(foodSearch.toLowerCase())));
 const count=cart.reduce((a,x)=>a+x.qty,0);
 $('#app').innerHTML=`<main class="customer-app">
 <div class="customer-ribbon"><span>COMER RICO. JUGAR MÁS. REPETIR. <b>✦</b> DIVERMANIA <b>✦</b> COMER RICO. JUGAR MÁS. REPETIR. <b>✦</b> DIVERMANIA <b>✦</b></span></div>
 <header class="customer-header customer-container">${clientBrand()}<nav class="customer-nav" aria-label="Navegación del cliente"><a href="#food-menu" data-action="scroll-food">Nuestro menú</a><a href="#how-to-order" data-action="scroll-how">Cómo pedir</a>${lastToken?`<a href="/?view=track&token=${encodeURIComponent(lastToken)}">Seguir mi pedido</a>`:''}</nav><div class="customer-header-actions"><button class="theme-switch" aria-label="Cambiar tema" data-action="theme">${icon('sun')}</button><button class="customer-cart-top" data-action="customer-cart">${icon('bag')}<span>Mi pedido</span><b>${count}</b></button></div></header>
 <div class="customer-container">${readPendingOrder()?`<button class="order-follow-banner full-width" data-action="recover-order">Recuperar el resultado de mi último envío ${icon('right')}</button>`:''}<div class="client-demo"><span>${preview?'VISTA PREVIA':'DIVERMANÍA'}</span> ${preview?'Vista previa del menú y las tarifas. Los pedidos de esta vista no llegan al negocio.':'Menú Divermanía · Personaliza tu pedido y sigue su preparación.'}</div>
 ${lastToken?`<a class="order-follow-banner" href="/?view=track&token=${encodeURIComponent(lastToken)}"><span class="pulse-dot"></span> Tu pedido tiene su propia pista. <strong>Ver seguimiento ${icon('right')}</strong></a>`:''}
 <section class="food-hero"><div class="food-hero-copy"><span class="hero-pill"><span>✦</span> EL PLAN COMPLETO ESTÁ AQUÍ</span><h1>EL ANTOJO<br>SE PIDE<br><em>A TU<br>MANERA.</em></h1><p>Tu hamburguesa favorita, una partida más y diversión para todos. Pide a tu gusto y sigue disfrutando.</p><button class="hero-order-button" data-action="scroll-food">¡Vamos a pedir! ${icon('right')}</button><div class="hero-location">${icon(mesa?'qr':'bag')} ${mesa?'Estás en la mesa '+esc(mesa):'Pide para retirar o selecciona delivery'}</div></div><div class="food-hero-visual"><img src="/assets/menu/burger.png" alt="Hamburguesa con queso y papas, fotografía ilustrativa del menú" width="912" height="771" fetchpriority="high"><div class="hero-photo-shade"></div><span class="hero-sideword" aria-hidden="true">ÑAM.</span><div class="flavor-seal"><span>MUCHO</span><strong>SABOR</strong><span>MUCHA DIVERSIÓN</span></div><div class="hero-photo-caption"><span>EL ANTOJO SE PIDE</span><strong>A TU MANERA.</strong><small>Imagen del menú · Ilustrativa</small></div></div></section>
 <section class="customer-perks" id="how-to-order" aria-label="Cómo hacer tu pedido"><div><span class="perk-number">01</span><span><strong>Elige tu antojo</strong><small>Todo lo rico en un solo lugar.</small></span>${icon('bag')}</div><div><span class="perk-number">02</span><span><strong>Hazlo a tu manera</strong><small>Quita lo que no te provoca.</small></span>${icon('settings')}</div><div><span class="perk-number">03</span><span><strong>Sigue disfrutando</strong><small>Te mostramos cuando esté listo.</small></span>${icon('bell')}</div></section>
 <section id="food-menu" class="food-menu-section"><div class="food-section-head"><div><span class="menu-kicker">AQUÍ EMPIEZA LO BUENO</span><h2>¿QUÉ TE <em>PROVOCA?</em></h2></div><div class="food-search">${icon('search')}<input id="food-search" aria-label="Buscar en el menú" placeholder="Busca tu próximo antojo…" value="${esc(foodSearch)}" autocomplete="off"></div></div><nav class="food-categories" aria-label="Categorías del menú">${categories.map(c=>`<button class="food-category ${menuCat===c?'active':''}" data-menu-cat="${esc(c)}" aria-pressed="${menuCat===c}"><span>${categorySymbol(c)}</span>${esc(c)}</button>`).join('')}</nav><div class="food-results"><span>${filtered.length} ${filtered.length===1?'opción para disfrutar':'opciones para disfrutar'}</span><span>${mesa?'Mesa '+esc(mesa):'Retiro / Delivery'} ${icon('down')}</span></div><div class="food-product-grid">${filtered.map((p,i)=>`<article class="food-product" style="--item-delay:${Math.min(i,5)*60}ms"><button class="food-product-photo ${esc(p.id)}" data-action="custom-product" data-id="${esc(p.id)}" aria-label="Personalizar ${esc(p.name)}">${foodPhoto(p)?`<img src="${esc(foodPhoto(p))}" alt="${esc(p.name)} · fotografía ilustrativa" loading="lazy" width="800" height="600">`:`<span class="food-fallback">${esc(p.emoji||'🍽️')}</span>`}${p.ingredients.length?'<span class="food-product-tag">A tu gusto ✦</span>':''}<span class="food-photo-arrow">${icon('arrow')}</span></button><div class="food-product-body"><span class="food-product-category">${esc(p.category)}</span><h3>${esc(p.name)}</h3><p>${esc(p.description||'Un antojo para acompañar la diversión.')}</p><div class="food-product-bottom"><div><small>Precio</small><strong>${money(p.price)}</strong></div><button class="food-add" data-action="custom-product" data-id="${esc(p.id)}" aria-label="Agregar ${esc(p.name)}"><span>Agregar</span>${icon('plus')}</button></div></div></article>`).join('')||`<div class="food-no-results">${empty('Ese antojo no está aquí todavía','Prueba otra búsqueda o categoría.','search')}<button class="btn" data-action="clear-food-search">Ver todo el menú</button></div>`}</div></section>
 <section class="playful-banner"><div class="playful-symbol" aria-hidden="true">✦</div><div><span>EL MEJOR COMBO ES EL PLAN.</span><h2>COME. JUEGA.<br><em>¡REPITE!</em></h2></div><div class="playful-banner-copy"><p>¿Viniste a la Play, al parque o por algo rico? Aquí todos tienen su plan.</p><span>${icon('game')} Zona gamer <b>·</b> ${icon('tree')} Parque infantil</span></div></section>
 ${packageSection()}<div class="no-phone-note">${icon('receipt')}<span><strong>¿Sin teléfono? También hay plan.</strong> Pide en caja, guarda tu número de turno y míralo en la pantalla del local.</span></div>
 <footer class="customer-footer">${clientBrand()}<span>Grandes antojos. Buenos momentos.<small>Fotografías ilustrativas · <a href="/assets/CREDITOS.txt" target="_blank" rel="noopener">Créditos de imágenes</a></small></span><a href="/admin.html">Acceso del equipo ${icon('external')}</a></footer></div>
 ${count?`<button class="customer-cart-float" data-action="open-cart"><span class="customer-cart-icon">${icon('bag')}<b>${count}</b></span><span>¡Ese antojo ya casi es tuyo!<strong>Ver mi pedido</strong></span><strong>${money(cartTotal())} ${icon('right')}</strong></button>`:''}
 </main>`;
}

function cartTotal(){return cart.reduce((a,x)=>a+(state.catalog.find(p=>p.id===x.productId)?.price||0)*x.qty,0);}
function customProduct(id){const p=state.catalog.find(p=>p.id===id);if(!p)return;if(!p.ingredients.length&&!p.options?.length){addCart(id,[]);return;}modal(esc(p.name),`<form id="custom-form"><div class="custom-product-summary">${foodPhoto(p)?`<img src="${esc(foodPhoto(p))}" alt="${esc(p.name)}">`:''}<div><span>HAZLO A TU MANERA</span><strong>${money(p.price)}</strong><small>${esc(p.description)}</small></div></div>${p.options?.length?`<div class="field"><label for="product-option">Elige tu opción</label><select id="product-option" name="productOption" required>${p.options.map(o=>`<option value="${esc(o.value||o.label||o)}">${esc(o.label||o.value||o)}</option>`).join('')}</select></div>`:''}<p class="form-note" style="margin:0 0 16px">Desmarca los ingredientes que no deseas.</p><div id="custom-modifiers">${p.ingredients.map((name,i)=>`<label class="check-line"><input type="checkbox" name="ingredient" value="${esc(name)}" checked><span>${esc(name)}</span></label>`).join('')}</div><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Cancelar</button><button class="btn primary" type="submit">Añadir · ${money(p.price)}</button></div></form>`);const choice=$('#product-option');if(choice){const refresh=()=>{const names=p.modifiersByOption?.[choice.value]?.length?p.modifiersByOption[choice.value]:(p.modifierNames||p.ingredients);$('#custom-modifiers').innerHTML=names.map(name=>`<label class="check-line"><input type="checkbox" name="ingredient" value="${esc(name)}" checked><span>${esc(name)}</span></label>`).join('');};choice.onchange=refresh;refresh();}$('#custom-form').onsubmit=e=>{e.preventDefault();const removed=$$('#custom-form input:not(:checked)').map(x=>x.value);addCart(id,removed,$('#custom-form select')?.value||'');closeModal();};}
function addCart(id,removed,option=''){if(readPendingOrder())return toast('Hay un pedido pendiente de recuperar. Usa el aviso del menú.',true);const key=id+':'+option+':'+removed.slice().sort().join('|');const found=cart.find(x=>x.key===key);if(found)found.qty=Math.min(20,found.qty+1);else cart.push({key,productId:id,qty:1,removed,option});saveClientCart();renderMenu();toast('Añadido a tu pedido.');}
function openCart(){const previous=$('#checkout-form');if(previous)for(const name of ['customerName','phone','address','notes','deliveryType'])if(previous.elements[name])checkoutDraft[name]=previous.elements[name].value;const mesa=params.get('mesa');modal('Tu pedido',`<form id="checkout-form"><div id="cart-lines">${cart.map((x,i)=>{const p=state.catalog.find(p=>p.id===x.productId);return p?`<div class="cart-row">${foodPhoto(p)?`<img class="cart-thumb" src="${esc(foodPhoto(p))}" alt="${esc(p.name)}">`:`<span class="item-emoji">${esc(p.emoji||'🍽️')}</span>`}<div><strong>${esc(p.name)}${x.option?' · '+esc(x.option):''}</strong>${x.removed.length?`<small>Sin: ${esc(x.removed.join(', '))}</small>`:`<small>${money(p.price)}</small>`}</div><div class="quantity"><button type="button" data-action="cart-minus" data-index="${i}" aria-label="Quitar unidad">−</button><span>${x.qty}</span><button type="button" data-action="cart-plus" data-index="${i}" aria-label="Agregar unidad">+</button></div></div>`:'';}).join('')}</div><div class="total-box"><span>Total del pedido</span><strong>${money(cartTotal())}</strong></div><div class="form-grid"><div class="field"><label for="checkout-name">Nombre</label><input id="checkout-name" name="customerName" required maxlength="100" autocomplete="name"></div><div class="field"><label for="checkout-phone">Teléfono · opcional en el local</label><input id="checkout-phone" name="phone" type="tel" maxlength="20" autocomplete="tel"></div></div>${mesa?`<div class="banner-info">Estás ordenando desde la mesa ${esc(mesa)}.</div>`:`<div class="field"><label for="delivery-type">Entrega</label><select id="delivery-type" name="deliveryType"><option value="Retiro">Retiro en el local</option><option value="Delivery">Delivery</option></select></div><div class="field" id="delivery-address" hidden><label for="checkout-address">Dirección de entrega</label><textarea id="checkout-address" name="address" maxlength="300"></textarea></div>`}<div class="field"><label for="checkout-notes">Observaciones · opcional</label><textarea id="checkout-notes" name="notes" placeholder="Ej. sin servilletas" maxlength="400"></textarea></div><p class="form-note">Recibirás un número de turno y podrás seguir el pedido en esta página. Esta operación no realiza el cobro ni emite una factura.</p><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Seguir eligiendo</button><button class="btn primary" type="submit">Confirmar pedido ${icon('right')}</button></div></form>`);const f=$('#checkout-form');for(const [name,value] of Object.entries(checkoutDraft))if(f.elements[name])f.elements[name].value=value;if(f.deliveryType)f.deliveryType.onchange=()=>{$('#delivery-address').hidden=f.deliveryType.value!=='Delivery';f.address.required=f.deliveryType.value==='Delivery';f.phone.required=f.deliveryType.value==='Delivery';};f.onsubmit=e=>{e.preventDefault();submit(f,async()=>{if(!cart.length)throw new Error('Agrega productos al pedido.');const r=await submitCustomerOrder({name:f.customerName.value,phone:f.phone.value,table:mesa||'Retiro',deliveryType:mesa?'Mesa':f.deliveryType.value,address:f.address?.value||'',notes:f.notes.value,items:cart.map(({productId,qty,removed,option})=>({productId,qty,removed,option}))});localStorage.setItem('divermania.lastToken',r.token);cart=[];saveClientCart();checkoutDraft={};closeModal();location.href=`/seguimiento.html?token=${encodeURIComponent(r.token)}`;});};}
let trackerPrevious='';
function renderTracker(){const token=params.get('token');const o=state.orders.find(o=>o.token===token);if(!o){$('#app').innerHTML=`<main class="tracker"><header class="public-header">${clientBrand()}</header>${empty('Pedido no encontrado','Revisa el enlace de seguimiento o consulta al personal.','bag')}<a class="btn full-width" href="/?view=menu">Volver al menú</a><p class="form-note">Comprueba que el enlace de seguimiento esté completo y consulta al encargado si el pedido no aparece.</p></main>`;return;}if(trackerPrevious&&trackerPrevious!==o.status&&o.status==='ready'){beep();if('Notification' in window&&Notification.permission==='granted'&&document.hidden)new Notification('¡Tu pedido está listo!',{body:`Pedido #${o.number}. Puedes acercarte al área de entrega.`,tag:'order-'+o.id,icon:'/mark.svg'});}trackerPrevious=o.status;const steps=['pending','preparing','ready','delivered'];const index=steps.indexOf(o.status);$('#app').innerHTML=`<main class="tracker"><header class="public-header">${clientBrand()}<span class="public-badge">Tu pedido</span></header><div class="demo-notice"><span class="tag">DEMO</span><span>${preview?'Seguimiento de prueba.':'Tu pedido se actualiza en tiempo real.'}</span></div><section class="tracker-head"><p>Tu número de turno es</p><div class="order-hero">#${o.number}</div><h2>${orderLabels[o.status]}</h2><p style="margin-top:8px">${o.table==='Retiro'?'Retiro en mostrador':'Mesa '+esc(o.table)}</p>${o.status==='ready'?'<div class="tracker-ready">¡Ya está! Acércate al área de entrega.</div>':''}${o.status==='cancelled'?'<div class="order-notes gap-top">Consulta al personal para conocer el motivo.</div>':`<div class="tracker-steps">${steps.map((s,i)=>`<div class="tracker-step ${index>=i?'done':''}"><i>${index>=i?'✓':i+1}</i>${orderLabels[s]}</div>`).join('')}</div>`}<div class="connection" style="justify-content:center"><span class="dot"></span>Esta página se actualiza automáticamente</div><button class="btn ${soundEnabled?'success':''} full-width gap-top" data-action="tracker-alert">${icon('bell')} ${soundEnabled?'Avisos activados en esta página':'Activar aviso cuando esté listo'}</button><p class="form-note">Mantén esta página abierta para recibir el aviso. Si cierras el navegador, esta página no puede notificarte.</p></section><section class="panel gap-top"><div class="panel-head"><h2>Lo que pediste</h2></div><div class="panel-body">${o.inventoryStatus==='partial'?'<div class="order-notes">Hay productos con receta o cantidades pendientes de configurar.</div>':''}<div class="order-items">${o.items.map(i=>`<div>${i.qty} × ${esc(i.name)}${i.removed?.length?`<small>Sin: ${esc(i.removed.join(', '))}</small>`:''}</div>`).join('')}</div><div class="order-line"><span>Total del pedido</span><strong>${money(o.total)}</strong></div></div></section><div class="actions gap-top"><a class="btn" href="/?view=menu${params.get('mesa')?'&mesa='+encodeURIComponent(params.get('mesa')):''}">Volver al menú</a><button class="btn" data-action="order-whatsapp" data-id="${o.id}">Compartir por WhatsApp</button></div><p class="form-note">Si no tienes teléfono, el personal puede entregarte tu número de turno y lo verás en la pantalla del local.</p></main>`;}
let boardReady=new Set(),boardInitialized=false;
function renderBoard(){const kind=params.get('kind')||'orders';const data=publicBoard(state,kind);let content='';if(kind==='orders'){const ready=data.orders.filter(o=>o.status==='ready');if(boardInitialized&&ready.some(o=>!boardReady.has(o.number)))beep();boardReady=new Set(ready.map(o=>o.number));boardInitialized=true;content=`<div class="board-columns"><section class="board-section"><h2>${icon('clock')} En preparación</h2><div class="turn-grid">${data.orders.filter(o=>o.status==='preparing').map(o=>`<div class="turn-number">${o.number}</div>`).join('')}</div>${!data.orders.some(o=>o.status==='preparing')?empty('Todo al día','Tu turno aparecerá aquí.','bag'):''}</section><section class="board-section ready"><h2>${icon('check')} Listos para retirar</h2><div class="turn-grid">${ready.map(o=>`<div class="turn-number">${o.number}</div>`).join('')}</div>${!ready.length?empty('En un momento','Aquí aparecerán los pedidos listos.','bag'):''}</section></div>`;}else if(kind==='gamer')content=`<div class="station-grid">${state.stations.map(s=>stationCard(s,true)).join('')}</div>`;else content=`<div class="station-grid">${active('park').map(t=>`<article class="station ${remaining(t)<=0?'expired':remaining(t)<=300000?'near':''}" data-session="${t.id}"><div class="station-top"><span>Pase #${t.number}</span>${badge('Parque','purple')}</div><div class="station-name">${t.minutes} minutos contratados</div><div class="station-time" data-countdown="${t.id}">${clock(remaining(t))}</div><div class="progress"><i data-progress="${t.id}" style="width:${Math.min(100,remaining(t)/(t.minutes*60000)*100)}%"></i></div></article>`).join('')||empty('El parque está listo','Los pases activos aparecerán aquí.','tree')}</div>`;$('#app').innerHTML=`<main class="board"><header class="board-header">${clientBrand()}<div><div class="board-clock" id="board-clock"></div><small class="text-center">${esc(connection.displayName||params.get('device')||'Disfruta. Nosotros llevamos el tiempo.')}</small></div></header><div class="order-line" style="margin-bottom:20px"><div class="board-title">${kind==='orders'?'Tu pedido, cada vez más cerca':kind==='gamer'?'Zona gamer · Cada partida cuenta':'Parque infantil · Tiempo para divertirse'}</div><button class="btn small" data-action="fullscreen">${icon('screen')} Pantalla completa</button></div>${content}<section class="board-promotion"><div class="board-promotion-photo"><img id="board-promo-image" src="/assets/menu/burger.png" alt="Hamburguesa del menú"></div><div><span>MIENTRAS DISFRUTAS</span><h2 id="board-promo-title">El antojo se pide a tu manera</h2><p id="board-promo-price">Comida, parque y zona gamer.</p></div><div class="board-promo-qr"><div id="board-menu-qr"></div><span>Escanea y pide</span></div></section><footer class="board-foot"><span><span class="dot"></span> ${preview?'Vista previa · Datos de prueba':'Firebase · Pantalla del local'}</span><div class="actions"><button class="btn small" data-action="sound">${icon('sound')} ${soundEnabled?'Sonido activado':'Activar sonido'}</button><a class="btn small" href="/admin.html">Centro de control</a></div></footer></main>`;tick();makeQR('board-menu-qr',location.origin+'/',90);}
async function enableSound(){try{audio??=new (window.AudioContext||window.webkitAudioContext)();await audio.resume();soundEnabled=!soundEnabled;if(soundEnabled)beep(true);render();toast(soundEnabled?'Avisos sonoros activados en este dispositivo.':'Sonido desactivado.');}catch{toast('Este navegador no permite activar el sonido.',true);}}
function beep(force=false){if(!soundEnabled&&!force||!audio)return;for(let i=0;i<2;i++){const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=i?740:620;g.gain.setValueAtTime(.0001,audio.currentTime+i*.23);g.gain.exponentialRampToValueAtTime(.12,audio.currentTime+i*.23+.02);g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+i*.23+.18);o.start(audio.currentTime+i*.23);o.stop(audio.currentTime+i*.23+.2);}}
function tick(){const now=serverTime();$$('[data-countdown]').forEach(el=>{const t=state.tickets.find(t=>t.id===el.dataset.countdown);if(t)el.textContent=clock(remaining(t,now));});$$('[data-progress]').forEach(el=>{const t=state.tickets.find(t=>t.id===el.dataset.progress);if(t)el.style.width=Math.min(100,remaining(t,now)/(t.minutes*60000)*100)+'%';});$$('[data-session]').forEach(el=>{const t=state.tickets.find(t=>t.id===el.dataset.session);if(!t)return;const ms=remaining(t,now);el.classList.toggle('near',ms>0&&ms<=300000);el.classList.toggle('expired',ms<=0);const label=el.querySelector('.station-top .badge');if(label&&t.area==='play'){label.textContent=ms<=0?'Finalizado':ms<=300000?'Por terminar':'En uso';label.className='badge '+(ms<=0?'red':ms<=300000?'orange':'purple');}});const bc=$('#board-clock');if(bc)bc.textContent=new Date(now).toLocaleTimeString('es-VE',{timeZone:'America/Caracas',hour:'2-digit',minute:'2-digit'});if(view==='staff'||view==='board'&&params.get('kind')!=='orders'){for(const t of active()){if(view==='staff'&&role==='gamer'&&t.area!=='play'||view==='board'&&params.get('kind')==='gamer'&&t.area!=='play'||view==='board'&&params.get('kind')==='park'&&t.area!=='park')continue;const ms=remaining(t,now),level=ms<=0?'end':ms<=60000?'one':ms<=300000?'five':'';const key=t.id+':'+t.endAt+':'+level;if(level&&!alarmSeen.has(key)){alarmSeen.add(key);if(!acknowledged.has(t.id)){beep();if(soundEnabled)toast(`${t.area==='play'?state.stations.find(s=>s.id===t.stationId)?.name:'Parque · pase #'+t.number}: ${ms<=0?'tiempo terminado':ms<=60000?'queda 1 minuto':'quedan menos de 5 minutos'}.`);}}if(ms<=0&&!acknowledged.has(t.id)&&soundEnabled){const bucket=Math.floor(now/20000);if(lastAlarmBucket!==String(bucket)){lastAlarmBucket=String(bucket);beep();}}}}}
async function nextOrder(id){const o=state.orders.find(o=>o.id===id);const next={pending:'preparing',preparing:'ready',ready:'delivered'}[o?.status];if(!next)return;try{await execute('order.status',{id,status:next});toast(orderLabels[next]+'.');}catch(e){toast(e.message,true);}}
async function whatsappOrder(id){const o=state.orders.find(o=>o.id===id);const message=`*DIVERMANIA · Pedido #${o.number}*\n${o.items.map(i=>`${i.qty}x ${i.name}${i.removed?.length?' (Sin: '+i.removed.join(', ')+')':''}`).join('\n')}\nTotal: ${money(o.total)}\n${o.deliveryType==='Delivery'?'Dirección: '+o.address+'\n':''}${o.notes?'Observaciones: '+o.notes+'\n':''}Seguimiento: ${location.origin}/?view=track&token=${encodeURIComponent(o.token)}`;window.open('https://wa.me/?text='+encodeURIComponent(message),'_blank','noopener');}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action],[data-page],[data-time-tab],[data-order-tab],[data-menu-cat]');if(!b)return;if(b.tagName==='A'&&b.getAttribute('href')==='#')e.preventDefault();if(b.dataset.page){page=b.dataset.page;search='';render();window.scrollTo(0,0);return;}if(b.dataset.timeTab){timeTab=b.dataset.timeTab;render();return;}if(b.dataset.orderTab){orderTab=b.dataset.orderTab;render();return;}if(b.dataset.menuCat){menuCat=b.dataset.menuCat;renderMenu();return;}const id=b.dataset.id;try{switch(b.dataset.action){case 'open-nav':$('.sidebar')?.classList.add('open');$('.mobile-cover')?.classList.add('show');break;case 'close-nav':$('.sidebar')?.classList.remove('open');$('.mobile-cover')?.classList.remove('show');break;case 'close-modal':closeModal();break;case 'help':help();break;case 'sign-out':await signOut();break;case 'import-menu':await importOfficialMenu();break;case 'new-station':createStation();break;case 'recover-order':{const attempt=readPendingOrder();if(attempt){const r=await submitCustomerOrder(attempt.payload);localStorage.setItem('divermania.lastToken',r.token);cart=[];saveClientCart();location.href='/seguimiento.html?token='+encodeURIComponent(r.token);}break;}case 'control-settings':controlSettings();break;case 'request-food':requestFood(id);break;case 'customer-cart':if(cart.length)openCart();else{toast('Elige un antojo para comenzar tu pedido.');scrollToSection('food-menu');}break;case 'scroll-food':e.preventDefault();scrollToSection('food-menu');break;case 'scroll-how':e.preventDefault();scrollToSection('how-to-order');break;case 'clear-food-search':foodSearch='';menuCat='Todos';renderMenu();break;case 'screen-wizard':screenWizard();break;case 'screen-guide':screenGuide();break;case 'prepared-screen':{const profile=screenProfiles().find(p=>p.id===id);if(profile)showPreparedScreen(profile);break;}case 'revoke-screen':await execute('device.revoke',{id});toast('Pantalla desvinculada.');break;case 'theme':{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';localStorage.setItem('divermania.theme',dark?'dark':'light');break;}case 'sound':await enableSound();break;case 'new-ticket':newTicket();break;case 'ticket-detail':ticketDetail(id);break;case 'start-picker':startPicker(id);break;case 'start-session':startSession(id,b.dataset.station||'');break;case 'session-detail':sessionDetail(id);break;case 'extend':extendSession(id);break;case 'acknowledge':acknowledged.add(id);toast('Alerta reconocida en este dispositivo.');break;case 'finish-session':modal('Finalizar sesión',`<p class="help-list">Confirma que la persona terminó de usar la estación o salió del parque. Esto liberará el espacio.</p><div class="modal-actions"><button class="btn" data-action="close-modal">Volver</button><button class="btn danger" data-action="finish-confirm" data-id="${id}">Confirmar salida</button></div>`);break;case 'finish-confirm':await execute('session.finish',{id});closeModal();toast('Sesión finalizada. Espacio disponible.');break;case 'new-customer':customerForm();break;case 'customer-detail':customerDetail(id);break;case 'confirm-payment':confirmPayment(id);break;case 'assign-customer':await execute('order.customer',{id,customerId:$('#assign-customer').value||null});closeModal();toast('Cliente asociado al pedido.');break;case 'order-detail':orderDetail(id);break;case 'order-next':await nextOrder(id);break;case 'cancel-order':modal('Cancelar pedido',`<p class="help-list">El pedido quedará cancelado en el control operativo. Si hubo un cobro, la devolución debe resolverse en el sistema de caja. Si el pedido aún no comenzó a prepararse, se devolverán los insumos reservados. Si ya está en preparación, no se devolverán automáticamente.</p><div class="modal-actions"><button class="btn" data-action="close-modal">Volver</button><button class="btn danger" data-action="cancel-confirm" data-id="${id}">Confirmar cancelación</button></div>`);break;case 'cancel-confirm':await execute('order.status',{id,status:'cancelled'});closeModal();toast('Pedido cancelado.');break;case 'print-order':printOrder(id);break;case 'new-order':newManualOrder();break;case 'legacy':window.open('/gestion.html?tab='+encodeURIComponent(b.dataset.tab||'pedidos'),'_blank','noopener');closeModal();break;case 'show-qr':qrModal();break;case 'screen-qr':qrModal(b.dataset.kind);break;case 'copy-link':await copy(b.dataset.url);break;case 'open-menu':window.open('/cliente.html','_blank','noopener');break;case 'open-board':window.open('/?view=board&kind='+encodeURIComponent(b.dataset.kind),'_blank','noopener');break;case 'open-role':window.open('/admin.html?role='+b.dataset.role+'&page='+({cash:'cash',entrance:'times',gamer:'times',kitchen:'orders'}[b.dataset.role]),'_blank','noopener');break;case 'custom-product':customProduct(id);break;case 'open-cart':openCart();break;case 'cart-minus':case 'cart-plus':{const x=cart[Number(b.dataset.index)];if(x)x.qty=Math.min(20,x.qty+(b.dataset.action==='cart-minus'?-1:1));cart=cart.filter(x=>x.qty>0);saveClientCart();if(!cart.length){closeModal();renderMenu();}else openCart();break;}case 'tracker-alert':if(!soundEnabled)await enableSound();if('Notification' in window&&Notification.permission==='default')await Notification.requestPermission();break;case 'order-whatsapp':whatsappOrder(id);break;case 'print':window.print();break;case 'fullscreen':if(!document.fullscreenElement)await document.documentElement.requestFullscreen();else await document.exitFullscreen();break;}}catch(err){formError(err);}});
function scrollToSection(id){document.getElementById(id)?.scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}
document.addEventListener('input',e=>{if(e.target.id==='food-search'){const pos=e.target.selectionStart;foodSearch=e.target.value;renderMenu();const input=$('#food-search');input.focus({preventScroll:true});input.setSelectionRange?.(pos,pos);}if(e.target.id==='customer-search'){const pos=e.target.selectionStart;search=e.target.value;render();const el=$('#customer-search');el.focus();el.setSelectionRange(pos,pos);}});
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('#modal-root .modal')){const els=$$('#modal-root button,#modal-root input,#modal-root select,#modal-root textarea,#modal-root a').filter(el=>!el.disabled&&!el.hidden);const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){last?.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first?.focus();e.preventDefault();}}});
subscribe(next=>{if(next.revision===state.revision)return;state=next;render();if(view==='menu'&&$('#checkout-form')){if(cart.length)openCart();else closeModal();}});
document.documentElement.dataset.theme=localStorage.getItem('divermania.theme')||'light';render();initialize().catch(err=>{connection.error=err.message;connection.status='error';render();});setInterval(tick,1000);
if(params.get('ticket')&&view==='staff'){const id=params.get('ticket');setTimeout(()=>startSession(id),200);}
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});

function loginScreen(){
 $('#app').innerHTML=`<main class="login"><img src="/logodivermania.png" alt="Divermanía" style="width:100px;height:82px;object-fit:contain"><h1>Acceso del equipo</h1><p>Entra con tu cuenta autorizada de Divermanía. Los permisos se verifican en Firebase.</p>${connection.error?`<div class="banner-info">${esc(connection.error)}</div>`:''}<form id="login-form"><div class="field"><label for="login-email">Correo</label><input type="email" id="login-email" name="email" autocomplete="username" required></div><div class="field"><label for="login-password">Contraseña</label><input type="password" id="login-password" name="password" autocomplete="current-password" required></div><button class="btn primary full-width" type="submit">Entrar</button><p id="login-error" role="alert" class="form-note"></p></form><a class="btn text gap-top" href="/">Volver al menú del cliente →</a><p class="form-note">Si aún no existe una cuenta del equipo, el administrador debe habilitar Authentication y asignar su rol. Publicar en GitHub no crea esos permisos.</p></main>`;
 const f=$('#login-form');f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('button');b.disabled=true;try{await signIn(f.email.value,f.password.value);}catch{$('#login-error').textContent='No fue posible iniciar sesión. Revisa la cuenta, su contraseña y la configuración de Firebase Authentication.';}finally{b.disabled=false;}};
}
function pairScreen(){
 $('#app').innerHTML=`<main class="board"><div class="pair-screen"><img src="/logodivermania.png" alt="Divermanía"><h1>Tu pantalla empieza aquí.</h1><p>En la computadora del administrador, abre “Pantallas y QR → Vincular pantalla”. Introduce aquí el código de 10 caracteres.</p>${connection.error?`<div class="banner-info">${esc(connection.error)}</div>`:''}<form id="pair-form"><div class="field"><label for="pair-code">Código de vinculación</label><input id="pair-code" name="code" placeholder="XXXXXXXXXX" maxlength="12" autocomplete="off" autocapitalize="characters" required></div><button class="btn primary full-width" type="submit">Vincular pantalla</button><p class="form-note" id="pair-error" role="alert"></p></form><p>El código vence a los 10 minutos y se utiliza una sola vez.</p></div></main>`;
 const f=$('#pair-form');f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('button');b.disabled=true;try{await pairDisplay(f.code.value);}catch(err){$('#pair-error').textContent=err.message;}finally{b.disabled=false;}};
}
async function importOfficialMenu(){
 const products=await fetch('/data/menu.json').then(r=>r.json());modal('Cargar el menú del PDF',`<div class="help-list"><p>Se cargarán ${products.length} productos y combos con los precios revisados del PDF. Los dos combos mixtos sin precio quedarán desactivados.</p><p>Los nombres que coincidan se actualizarán conservando sus recetas. Los productos que ya existen y no aparecen en el PDF no se eliminarán.</p><p>No se inventarán gramajes: las recetas nuevas quedan pendientes de configurar. Este paso escribe en tu catálogo de Firebase cuando confirmes.</p></div><div class="modal-actions"><button class="btn" data-action="close-modal">Volver</button><button class="btn primary" id="confirm-import">Confirmar carga del menú</button></div>`);$('#confirm-import').onclick=async()=>{const b=$('#confirm-import');b.disabled=true;try{const result=await execute('catalog.import',{products});closeModal();toast(result.count+' productos procesados.');}catch(err){formError(err);b.disabled=false;}};
}
function createStation(){modal('Configurar una estación gamer',`<form id="station-form"><div class="field"><label for="station-name">Nombre de la estación</label><input id="station-name" name="stationName" placeholder="Ej. Play 1" required maxlength="50"></div><p class="form-note">Registra únicamente las estaciones que realmente existen en el local.</p><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Volver</button><button class="btn primary" type="submit">Guardar estación</button></div></form>`);const f=$('#station-form');f.onsubmit=e=>{e.preventDefault();submit(f,async()=>{await execute('station.save',{name:f.stationName.value});closeModal();toast('Estación guardada.');});};}
function voucherList(){const list=state.vouchers||[];return `<section class="panel gap-top"><div class="panel-head"><div><h2>Comida incluida en los pases</h2><p>Un canje por paquete. El tipo de perro se elige al solicitarlo a cocina.</p></div></div>${list.filter(v=>v.status==='pending').map(v=>`<div class="ticket-row"><span class="ticket-icon">${icon('bag')}</span><div><strong>Pase #${v.ticketNumber}</strong><p>${v.items.map(x=>x==='hotdog'?'Perro del paquete':'Cotufas').join(' + ')}</p></div><button class="btn small" data-action="request-food" data-id="${v.id}">Solicitar a cocina</button></div>`).join('')||empty('Sin canjes pendientes','Las compras de paquetes con comida aparecen aquí.','bag')}</section>`;}
function requestFood(id){const voucher=state.vouchers.find(v=>v.id===id);if(!voucher)return;const dogs=state.catalog.filter(p=>p.cat==='perros'&&p.enabled!==false&&(preview||p.id===state.settings?.hotdogProductId));modal('Comida del pase #'+voucher.ticketNumber,`<form id="food-form">${voucher.items.includes('hotdog')?`<div class="field"><label for="food-product">Perro incluido · definido por administración</label><select name="productId" id="food-product" required><option value="">Selecciona el producto que corresponde</option>${dogs.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div>`:''}<p class="form-note">${!preview&&!state.settings?.hotdogProductId?'El administrador debe definir qué perro incluye el paquete en “Parque y comida incluida”. ':''}El canje crea un pedido de cocina pagado por el paquete. Los insumos configurados se descuentan una sola vez. Las cotufas requieren su insumo o receta configurada.</p><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Volver</button><button class="btn primary" type="submit">Enviar a cocina</button></div></form>`);const f=$('#food-form');f.onsubmit=e=>{e.preventDefault();submit(f,async()=>{await execute('food.request',{id,productId:f.productId?.value||null});closeModal();toast('Canje enviado a cocina.');});};}

function newManualOrder(){window.open('/gestion.html?tab=manual','_blank','noopener');}

function packageSection(){return `<section class="packages-section"><div class="food-section-head"><div><span class="menu-kicker">EL PLAN SIGUE DESPUÉS DE COMER</span><h2>PARQUE <em>Y GAMER</em></h2></div><span class="form-note">Compra y paga tu pase en taquilla.</span></div><div class="packages-grid">${Object.entries(packages).map(([area,plans])=>`<article><h3>${icon(area==='park'?'tree':'game')}${area==='park'?'Parque infantil':'Zona gamer'}</h3>${plans.map(p=>`<div><span>${packageLabel(p)}</span><strong>${money(p.price)}</strong></div>`).join('')}</article>`).join('')}</div><p class="form-note">Control adicional: $1,30 · Modalidad de cobro pendiente de confirmar.</p><div class="opening-hours"><h3>Nuestro horario</h3>${schedules.map(s=>`<span><strong>${s.days}</strong> ${s.open}–${s.close}</span>`).join('')}</div></section>`;}

let promotionIndex=0;setInterval(()=>{if(view!=='board')return;const products=state.catalog.filter(p=>p.enabled!==false&&p.image);if(!products.length)return;const p=products[(promotionIndex++)%products.length],img=$('#board-promo-image');if(img){img.src=p.image;img.alt=p.name;$('#board-promo-title').textContent=p.name;$('#board-promo-price').textContent=money(p.price);}},15000);

function controlSettings(){const settings=state.settings||{},dogs=state.catalog.filter(p=>p.cat==='perros'&&p.enabled!==false);modal('Parque y comida de los paquetes',`<form id="settings-form"><div class="field"><label for="park-capacity">Capacidad del parque · deja vacío si no está definida</label><input id="park-capacity" name="capacity" type="number" min="1" max="500" value="${state.capacity??''}"></div><div class="field"><label for="package-hotdog">Perro incluido en los paquetes</label><select id="package-hotdog" name="hotdogProductId"><option value="">Pendiente de confirmar</option>${dogs.map(p=>`<option value="${p.id}" ${settings.hotdogProductId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><h3>Receta de una porción de cotufas</h3><p class="form-note">Escribe las cantidades exactas por porción. No se rellenan gramajes de ejemplo.</p>${Object.entries(state.inventory||{}).map(([id,ing])=>`<div class="field" style="display:grid;grid-template-columns:1fr 90px;align-items:center"><label for="popcorn-${id}">${esc(ing.name)} (${esc(ing.unit)})</label><input id="popcorn-${id}" data-popcorn-id="${id}" type="number" min="0" step="0.01" value="${settings.popcornRecipe?.find(x=>x.id===id)?.qty||0}"></div>`).join('')}<div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Volver</button><button class="btn primary" type="submit">Guardar configuración</button></div></form>`,true);const f=$('#settings-form');f.onsubmit=e=>{e.preventDefault();submit(f,async()=>{const popcornRecipe=$$('[data-popcorn-id]').filter(x=>Number(x.value)>0).map(x=>({id:x.dataset.popcornId,qty:Number(x.value)}));await execute('config.save',{capacity:f.capacity.value?Number(f.capacity.value):null,hotdogProductId:f.hotdogProductId.value||null,popcornRecipe});closeModal();toast('Configuración guardada.');});};}

function readPendingOrder(){try{return JSON.parse(localStorage.getItem('divermania.pending-order')||'null');}catch{return null;}}
async function submitCustomerOrder(payload){let attempt=readPendingOrder();if(attempt&&JSON.stringify(attempt.payload)!==JSON.stringify(payload))throw new Error('Hay un envío pendiente. Recupera su resultado desde el aviso del menú antes de cambiar el pedido.');attempt ||= {key:uid(),payload};localStorage.setItem('divermania.pending-order',JSON.stringify(attempt));try{const result=await execute('order.create',payload,attempt.key);localStorage.removeItem('divermania.pending-order');return result;}catch(error){if(preview||['functions/invalid-argument','functions/failed-precondition','functions/permission-denied','functions/not-found','functions/unauthenticated','functions/resource-exhausted'].includes(error.code))localStorage.removeItem('divermania.pending-order');throw error;}}
